import { Step } from './types';

export class Loop {
  private retryCount: number = 0;

  async executeStep(step: Step): Promise<void> {
    while (this.retryCount < 5) {
      try {
        await step.run();
        this.retryCount = 0; // Reset retry count on success
        break;
      } catch (error) {
        this.retryCount++;
        console.error(`Step ${step.id} failed. Retrying... (Retry ${this.retryCount}/5)`);
      }
    }
    if (this.retryCount >= 5) {
      throw new Error(`Step ${step.id} failed after 5 retries`);
    }
  }
}

